pub const WEAPONS: &[WeaponDef] = &[
    WeaponDef { id: "wp_axe", name: "消防斧", desc: "浸过硝烟的钝刃，斧柄上还留着上一个轮回里紧握到发白的指痕。它不锋利，但它从不会先你一步松手。", tier: 0, dmg: (22, 34), ammo: None, dmg_type: DamageType::Kinetic, special: &[], base_price: 0, need_grade: None },
    WeaponDef { id: "wp_gun9", name: "9mm 手枪", desc: "六发子弹，六次把死亡往后推的机会。弹匣空了的那天，你要学会用别的东西活命。", tier: 0, dmg: (14, 20), ammo: Some(6), dmg_type: DamageType::Kinetic, special: &[], base_price: 0, need_grade: None },
    WeaponDef { id: "wp_sword", name: "军用刺刀军刀", desc: "军规量产的冷刃，握柄的编号已被血磨得看不清。它见证过太多待续的轮回，你只是下一个。", tier: 0, dmg: (10, 16), ammo: None, dmg_type: DamageType::Kinetic, special: &[], base_price: 0, need_grade: None },
    WeaponDef { id: "wp_katana", name: "精锻武士刀", desc: "刀身如镜，映出的却是你身后那个不属于这个世界的影子。每一次拔刀，都像在问：这次，谁会先倒。", tier: 1, dmg: (16, 24), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(2)], base_price: 1200, need_grade: Some('C') },
    WeaponDef { id: "wp_gauss", name: "高斯手枪", desc: "线圈嗡鸣的一瞬，时间仿佛被拉长。主神空间里的每一把枪，都装满了「再也回不去」的念头。", tier: 1, dmg: (20, 30), ammo: Some(10), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((0, 0))], base_price: 1400, need_grade: None },
    WeaponDef { id: "wp_emi", name: "电磁脉冲枪", desc: "它不杀人，它只是让所有依赖电子的东西短暂失控。可到了最后，最先失控的往往是持枪的人。", tier: 2, dmg: (24, 36), ammo: Some(8), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.15)], base_price: 3000, need_grade: Some('B') },
    WeaponDef { id: "wp_holy_sword", name: "圣裁十字剑", desc: "剑锷雕着十字，剑锋却冷得没有半点慈悲。所谓圣裁，不过是谁的信念先撑到另一个人倒下。", tier: 2, dmg: (26, 38), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Burn((0, 0))], base_price: 3600, need_grade: Some('B') },
    WeaponDef { id: "wp_silver_gun", name: "礼装银弹手枪", desc: "银弹只对「某些东西」有用。你心知肚明——真正该提防的，是那些披着人皮的不眠之物。", tier: 2, dmg: (22, 34), ammo: Some(6), dmg_type: DamageType::Silver, special: &[WeaponSpecial::Stun(0.0)], base_price: 3400, need_grade: Some('C') },
    WeaponDef { id: "wp_cu_ju", name: "问心·青锋剑", desc: "剑名问心，问的是持剑人一句话都不敢答的旧事。剑越锋利，越能听见自己心里那点没抖干净的怕。", tier: 3, dmg: (30, 46), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(4)], base_price: 8000, need_grade: Some('A') },
    WeaponDef { id: "wp_quantum_core", name: "量子核心振荡剑", desc: "剑刃在叠加态里明明灭灭，砍中之前，它同时存在于每一个可能的世界线。你握住的，是无数个「万一」。", tier: 3, dmg: (34, 50), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.0)], base_price: 11000, need_grade: Some('A') },
    // ---- 增量扩充（第 2 批 · tier 1~3 各流派）----
    WeaponDef { id: "wp_scythe_pobing", name: "破军重镰", desc: "镰锋豁口累累，每一道都是上个主人留下的一次死里逃生。它收割的不只是命，还有你最后的犹豫。", tier: 1, dmg: (28, 42), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(3)], base_price: 1600, need_grade: Some('C') },
    WeaponDef { id: "wpn_bloodsaber", name: "血戮剑", desc: "剑身饮过太多血，挥动时会有低低的回响，像一群亡魂在替你清点战果。越砍，心越冷。", tier: 2, dmg: (26, 40), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Leech(6)], base_price: 3800, need_grade: Some('B') },
    WeaponDef { id: "wpn_zhuai_jianpan", name: "诛仙剑阵盘", desc: "一方残破的剑阵盘，里面封着道门前辈的半截执念。展开的刹那，成百上千道剑光只为「诛」一个名字。", tier: 3, dmg: (36, 54), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 3)), WeaponSpecial::Stun(0.0)], base_price: 16000, need_grade: Some('A') },
    WeaponDef { id: "wp_quantum_annihil", name: "量子湮灭刀", desc: "正反物质在刀锋相撞，把「存在」本身撕成碎片。它连挥刀的人都怕——怕自己成为下一个被湮灭的坐标。", tier: 3, dmg: (40, 58), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.2)], base_price: 20000, need_grade: Some('A') },
    WeaponDef { id: "wp_gravity_collapse", name: "引力坍缩炮", desc: "一颗微缩的星在炮口崩塌，连光都逃不出去。开炮的代价，是你离「回家」又远了一个光年。", tier: 3, dmg: (45, 60), ammo: Some(4), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.25)], base_price: 24000, need_grade: Some('A') },
    WeaponDef { id: "wpn_shihun_fan", name: "噬魂幡", desc: "幡上绣着的符咒会呼吸，猎猎作响时，像有万千道目光在幡布后盯着你。它吞掉别人的魂，也一点点啃你的理智。", tier: 2, dmg: (24, 36), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Stun(0.0), WeaponSpecial::Burn((2, 2))], base_price: 4200, need_grade: Some('B') },
    WeaponDef { id: "wpn_taixu_godsaw", name: "太虚神剑", desc: "剑出太虚，无门无派，只认一个「斩」字。传说它从不缺主人，缺的是肯为它把名字从生死簿上划掉的人。", tier: 3, dmg: (38, 56), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Pierce(5)], base_price: 22000, need_grade: Some('A') },
    WeaponDef { id: "wpn_rail_sniper", name: "电磁轨道狙击枪", desc: "三发轨道弹，三次隔着千山万水取人性命的机会。瞄准镜里，你终于看清了自己冷得发硬的眼睛。", tier: 2, dmg: (32, 48), ammo: Some(3), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(6)], base_price: 9800, need_grade: Some('B') },
    WeaponDef { id: "wpn_nano_whip", name: "纳米切割鞭", desc: "亿万纳米刃在鞭梢聚集，抽出去的是风，落下来的是被切到分子级的绝望。它太顺滑，顺手得让人上瘾。", tier: 2, dmg: (22, 34), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((4, 2)), WeaponSpecial::Stun(0.1)], base_price: 7200, need_grade: Some('B') },
    WeaponDef { id: "wpn_causality_sword", name: "因果律护身剑", desc: "这柄剑不斩肉身，斩的是「因」。它护你一次，就从你命里借走一段偿还不起的「果」。", tier: 3, dmg: (34, 50), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(5), WeaponSpecial::Stun(0.15)], base_price: 26000, need_grade: Some('S') },
    // ==================== 增量扩充（第 3 批 · +60 武器 · 五流派） ====================
    // ---- 动漫系（11）----
    WeaponDef { id: "wp_zanjingdao_he", name: "斩魄刀·卍解", desc: "卍解——灵魂解放后的终解，刀灵与持刀者共鸣，每一次挥斩都带着死神的低语。你听见的，是自己的名字在逐渐淡去。", tier: 2, dmg: (30, 46), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 3))], base_price: 6800, need_grade: Some('B') },
    WeaponDef { id: "wp_ruyibang", name: "如意金箍棒", desc: "重一万三千五百斤，却只愿听一句「大」。它等的主人，早把名字写进了谁的传说，又把自由押给了谁。", tier: 3, dmg: (42, 62), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Stun(0.2), WeaponSpecial::Pierce(4)], base_price: 23000, need_grade: Some('A') },
    WeaponDef { id: "wp_excalibur_holy", name: "誓约胜利之剑", desc: "剑身盛满星辰，出鞘便要完成一场无人记得的誓约。它选的王已不再回来，只剩这束光，替你照着回去的路。", tier: 3, dmg: (46, 64), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Burn((4, 3)), WeaponSpecial::Leech(4)], base_price: 30000, need_grade: Some('S') },
    WeaponDef { id: "wp_beam_saber", name: "光束军刀", desc: "高热光束在剑柄凝固成刃，嗡鸣声像一句警告。它不需要鞘，因为它从不原谅举棋不定的人。", tier: 2, dmg: (36, 50), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((5, 2)), WeaponSpecial::Stun(0.1)], base_price: 8800, need_grade: Some('A') },
    WeaponDef { id: "wp_zanyue", name: "斩月大刀", desc: "刀身比人还宽，重得连月光都压弯了半截。挥它的人，必须连自己的那一半软弱一起斩下去。", tier: 2, dmg: (34, 52), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Pierce(5)], base_price: 7600, need_grade: Some('B') },
    WeaponDef { id: "wp_qianbenying", name: "千本樱·散舞", desc: "刀碎成千万片，像一场不散的樱花雨。每一片都美，每一片也都致命——正如这个轮回里所有的温柔。", tier: 2, dmg: (28, 42), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(3), WeaponSpecial::Stun(0.15)], base_price: 7000, need_grade: Some('B') },
    WeaponDef { id: "wp_niutou_ren", name: "牛头虚刃", desc: "虚与死神之间，有一道谁也不敢跨的门。这柄刃曾卡在门缝里，如今到了你手上，替你守那道门。", tier: 3, dmg: (40, 60), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Leech(8), WeaponSpecial::Stun(0.15)], base_price: 21000, need_grade: Some('A') },
    WeaponDef { id: "wp_wang_zhicai", name: "王之财宝·宝具齐射", desc: "黄金之门在身后洞开，无数宝具如雨点齐射。王者的财宝里，唯独没有一样能买回「活着」。", tier: 3, dmg: (44, 58), ammo: Some(6), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(6)], base_price: 26000, need_grade: Some('A') },
    WeaponDef { id: "wp_guaili_jian", name: "乖离剑·EA", desc: "开天辟地之剑，剑刃旋转时，世界像一本被重新装订的书。它不屑与你并肩，它只差遣你为它翻页。", tier: 3, dmg: (52, 70), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.3), WeaponSpecial::Burn((6, 3))], base_price: 36000, need_grade: Some('S') },
    WeaponDef { id: "wp_long_ji", name: "龙骑兵系统", desc: "十二架浮游炮绕着你盘旋，像一群驯服了的流星。它们替你死，替你哭，却唯独替不了你回家。", tier: 2, dmg: (32, 48), ammo: Some(12), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 2)), WeaponSpecial::Stun(0.1)], base_price: 9000, need_grade: Some('A') },
    WeaponDef { id: "wp_death_scythe_q", name: "死神镰刀·终焉", desc: "镰尖指向之处，一切轮回的故事都要收场。它不是结束，它只是那个终于肯来接你的「最后一页」。", tier: 3, dmg: (46, 62), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(10)], base_price: 32000, need_grade: Some('S') },
    // ---- 仙侠小说系（11）----
    WeaponDef { id: "wp_feijian_qingyun", name: "青云飞剑", desc: "御剑青云间，一剑破长风。剑随心动，心却回不到那座再也不敢回望的山门。", tier: 1, dmg: (24, 36), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Pierce(3)], base_price: 3600, need_grade: Some('C') },
    WeaponDef { id: "wp_shenbing_ling", name: "神兵·灵天刃", desc: "刃含一缕天灵，出鞘便有云气相随。它认主极挑，只肯为「还愿」的人染血。", tier: 2, dmg: (34, 48), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 3)), WeaponSpecial::Pierce(3)], base_price: 9200, need_grade: Some('B') },
    WeaponDef { id: "wp_zhanxian_feidao", name: "斩仙飞刀", desc: "刀出如电，专斩「仙」字辈。可惜飞的再快，也快不过生死簿上那笔已落的墨。", tier: 3, dmg: (42, 58), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.25)], base_price: 24000, need_grade: Some('A') },
    WeaponDef { id: "wp_fantian_yin", name: "翻天印", desc: "印起翻山，印落覆海。天地有名当敬畏，此印无名，所以不敬。", tier: 3, dmg: (48, 66), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Stun(0.3)], base_price: 28000, need_grade: Some('A') },
    WeaponDef { id: "wp_zhuxian_sijian", name: "诛仙四剑·合一", desc: "诛仙、戮仙、陷仙、绝仙，四剑归一成一念。合剑的人，先要合住自己心里那把「仙」。", tier: 3, dmg: (56, 76), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((6, 4)), WeaponSpecial::Pierce(6)], base_price: 40000, need_grade: Some('S') },
    WeaponDef { id: "wp_xuanyuan_jian", name: "轩辕剑·人皇", desc: "人皇之兵，山河之重。若你不能替苍生担当，它也只是一柄华而不实的王者玩具。", tier: 3, dmg: (50, 68), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Burn((5, 3)), WeaponSpecial::Leech(5)], base_price: 34000, need_grade: Some('S') },
    WeaponDef { id: "wp_pangu_fu", name: "盘古开天斧", desc: "开天辟地的那一斧，如今还留着半声回响。谁握着它，谁就得扛起「再造一方天地」的妄想。", tier: 3, dmg: (58, 80), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(8), WeaponSpecial::Stun(0.2)], base_price: 46000, need_grade: Some('S') },
    WeaponDef { id: "wp_kongtong_yin", name: "崆峒印", desc: "上古神印，落处自有皇道气运镇压。你握住的，是一个早已亡了国度的最后一点龙气。", tier: 2, dmg: (30, 44), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Stun(0.2), WeaponSpecial::Leech(2)], base_price: 8600, need_grade: Some('B') },
    WeaponDef { id: "wp_taiji_tu", name: "太极图", desc: "阴阳流转，图为太极。它把敌我的力气都借去搅成一股，最后还你一个不偏不倚的「空」。", tier: 3, dmg: (40, 54), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((4, 4)), WeaponSpecial::Stun(0.15)], base_price: 22000, need_grade: Some('A') },
    WeaponDef { id: "wp_shanhe_shetu", name: "山河社稷图", desc: "一图藏尽山河，展开便是另一个世界的缩影。你不知是自己进了画，还是画一直没放你出来。", tier: 3, dmg: (44, 60), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Stun(0.2), WeaponSpecial::Leech(4)], base_price: 30000, need_grade: Some('S') },
    WeaponDef { id: "wp_xihe_zhen", name: "曦和神针", desc: "一针挑破黑夜，曦光顺着针尖淌进来。它记住的不是伤，是破晓前那个没敢睡去的你。", tier: 2, dmg: (26, 38), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.1), WeaponSpecial::Burn((3, 2))], base_price: 6400, need_grade: Some('B') },
    // ---- 科幻系（11）----
    WeaponDef { id: "wp_gauss_rifle", name: "高斯步枪", tier: 2, dmg: (36, 52), ammo: Some(12), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 2))], base_price: 9800, need_grade: Some('B'), desc: "电磁线圈把弹丸加速到看不见，等你看清弹孔，命已经交了出去。它不信运气，只信初速。" },
    WeaponDef { id: "wp_particle_cannon", name: "粒子炮", tier: 3, dmg: (50, 66), ammo: Some(4), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((5, 3)), WeaponSpecial::Stun(0.15)], base_price: 26000, need_grade: Some('A'), desc: "一束高能粒子足以让目标「蒸发」成基本粒子。开炮时，你听见的不是轰鸣，是宇宙对渺小的嘲笑。" },
    WeaponDef { id: "wp_electromag_gun", name: "电磁加速炮", tier: 2, dmg: (40, 56), ammo: Some(6), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(6)], base_price: 12000, need_grade: Some('A'), desc: "磁轨上的弹丸记得每一次加速，就像你记得每一次没敢开枪的瞬间。扳机扣下，过去就回不去了。" },
    WeaponDef { id: "wp_plasma_dagger", name: "等离子刺刃", tier: 1, dmg: (26, 38), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 3))], base_price: 4200, need_grade: Some('C'), desc: "袖里藏着一小截太阳，贴身时连空气都被烧得发白。它适合近处，也最适合那些避不开的近处。" },
    WeaponDef { id: "wp_antimatter_round", name: "反物质湮灭弹", tier: 3, dmg: (60, 78), ammo: Some(2), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((8, 3)), WeaponSpecial::Stun(0.2)], base_price: 42000, need_grade: Some('S'), desc: "两发。正反物质相遇即湮灭，把「存在」从坐标上抹去。你只剩两次机会，用它或不用，都是选择。" },
    WeaponDef { id: "wp_orbital_gun", name: "轨道天基枪", tier: 3, dmg: (48, 64), ammo: Some(3), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(8)], base_price: 30000, need_grade: Some('A'), desc: "枪口直指天顶，真正的杀意来自几万公里的轨道之上。你抬头的那一刻，其实早已逃不脱它的准星。" },
    WeaponDef { id: "wp_laser_sword", name: "纯激光剑", tier: 2, dmg: (38, 54), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((5, 3)), WeaponSpecial::Stun(0.1)], base_price: 10000, need_grade: Some('B'), desc: "没有重量，只有一道不肯熄灭的光。它切开的不是血肉，是黑暗里最后一点犹豫。" },
    WeaponDef { id: "wp_nano_blade", name: "纳米蜂巢剑", tier: 2, dmg: (32, 46), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Leech(4), WeaponSpecial::Pierce(4)], base_price: 8200, need_grade: Some('B'), desc: "剑身是亿万纳米机器组成的蜂巢，能随你的心意重组。你握住的，是可塑性，也是某种不祥的顺从。" },
    WeaponDef { id: "wp_phase_weapon", name: "相位扰动枪", tier: 2, dmg: (34, 50), ammo: Some(8), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.3)], base_price: 9400, need_grade: Some('B'), desc: "它打的不是实体，是「相位」。命中的目标会短暂与现实脱节，像一场终究要回来的噩梦。" },
    WeaponDef { id: "wp_warpspeed_round", name: "曲速托卡马克枪", tier: 3, dmg: (52, 70), ammo: Some(3), dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.25), WeaponSpecial::Burn((6, 3))], base_price: 36000, need_grade: Some('S'), desc: "弹头里蜷着一团曲速场的雏形，出膛即扭曲一瞬的时空。可惜这世上，只有死亡比光速更快抵达。" },
    WeaponDef { id: "wp_rail_pistol", name: "微型轨道手枪", tier: 1, dmg: (28, 40), ammo: Some(6), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(4)], base_price: 5000, need_grade: Some('C'), desc: "缩小到掌心的轨道炮，藏得住杀意，藏不住扣扳机时那一下微微的迟疑。" },
    // ---- 魔幻系（11）----
    WeaponDef { id: "wp_arcan_staff", name: "奥术增幅法杖", tier: 2, dmg: (24, 40), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((4, 3))], base_price: 7800, need_grade: Some('B'), desc: "杖顶的奥术之核会把你的咒语放大成灾。它不问你懂不懂魔法，只问你还记不记得自己为何而战。" },
    WeaponDef { id: "wp_madoushu_grimoire", name: "禁忌魔导书", tier: 3, dmg: (38, 56), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Burn((6, 3)), WeaponSpecial::Leech(4)], base_price: 25000, need_grade: Some('A'), desc: "书页上没有字，只有一行行洗不掉的旧血。每翻一页，就有一段被抹去的知识，顺着你的眼睛爬进来。" },
    WeaponDef { id: "wp_xianzhe_zhi_shi", name: "贤者之石刃", tier: 3, dmg: (44, 62), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(8), WeaponSpecial::Stun(0.15)], base_price: 29000, need_grade: Some('A'), desc: "贤者之石锻成的刃，能把触碰的一切都「点成黄金」——包括你不想失去的人。它给的越多，越像一场等价交换的谎言。" },
    WeaponDef { id: "wp_dragon_lance", name: "龙枪·屠龙", tier: 2, dmg: (40, 56), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(6)], base_price: 11000, need_grade: Some('B'), desc: "枪尖嗜过龙血，至今还带着一股不肯散去的腥。屠龙者终成恶龙，这柄枪最清楚这句话的下半句。" },
    WeaponDef { id: "wp_shuang_zhi_aisang", name: "霜之哀伤", tier: 3, dmg: (48, 64), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Burn((7, 3)), WeaponSpecial::Leech(6)], base_price: 33000, need_grade: Some('S'), desc: "剑身冰封着亡者的低语，挥动时霜花顺刃而下。每吸取一条命，剑上就多一道你认不出的脸。" },
    WeaponDef { id: "wp_leidun_chui", name: "雷神之锤·妙尔尼尔", tier: 3, dmg: (50, 68), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.3), WeaponSpecial::Burn((5, 3))], base_price: 34000, need_grade: Some('S'), desc: "唯有「配得上」它的人方能举起。雷声落下时，你可听见那头雷霆里，藏着一个神祇未尽的孤独。" },
    WeaponDef { id: "wp_sheng_jian_mj", name: "光之圣剑", tier: 2, dmg: (36, 52), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Burn((4, 3))], base_price: 9000, need_grade: Some('B'), desc: "剑身由纯粹的圣光凝成，照得见你所有的谎。被它刺中的不是敌人，是你还想伪装下去的真相。" },
    WeaponDef { id: "wp_mo_jian_zhl", name: "诅咒魔剑·噬主", tier: 2, dmg: (38, 54), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(8)], base_price: 10500, need_grade: Some('B'), desc: "它把敌人的生气转给你，也把主人的魂魄一点点抽走。这把剑从不挑食，你我不是它的第一顿。" },
    WeaponDef { id: "wp_lieyan_jian", name: "烈焰之剑·火舞", tier: 1, dmg: (30, 44), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((5, 3))], base_price: 4800, need_grade: Some('C'), desc: "剑上跃着永不熄灭的火舌，像一场被钉死在刃上的舞蹈。它暖得了黑夜，也烧得穿誓言。" },
    WeaponDef { id: "wp_hanbing_gong", name: "寒冰精灵长弓", tier: 2, dmg: (30, 46), ammo: Some(8), dmg_type: DamageType::Silver, special: &[WeaponSpecial::Burn((3, 2)), WeaponSpecial::Stun(0.2)], base_price: 8800, need_grade: Some('B'), desc: "弓弦凝着寒霜，拉满时会落下一串冰晶。它射出的不是箭，是某种被冻住的、说不出的话。" },
    WeaponDef { id: "wp_zhigu_shenju", name: "翡翠贤杖·自然", tier: 1, dmg: (22, 34), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Leech(3), WeaponSpecial::Burn((2, 2))], base_price: 4000, need_grade: Some('C'), desc: "杖身盘着藤蔓，顶端的新叶四季不凋。它把根须悄悄伸进你的影子里，替你记着每一寸走过的泥泞。" },
    // ---- 武侠系（11）----
    WeaponDef { id: "wp_yitian_jian", name: "倚天剑", tier: 2, dmg: (38, 54), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Pierce(5), WeaponSpecial::Stun(0.1)], base_price: 9600, need_grade: Some('B'), desc: "倚天不出，谁与争锋。剑锋所向，是这乱世里最后一点不肯折断的傲气。" },
    WeaponDef { id: "wp_tulong_dao", name: "屠龙宝刀", tier: 2, dmg: (42, 58), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(6)], base_price: 10800, need_grade: Some('B'), desc: "宝刀屠龙，号令天下。刃上那道豁口，是上一代英雄用命换来的半句传说。" },
    WeaponDef { id: "wp_dagou_bang", name: "打狗棒·逍遥", tier: 1, dmg: (24, 36), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Stun(0.15)], base_price: 3800, need_grade: Some('C'), desc: "见棒如见丐帮，棒影起处，从来不争输赢，只争一个「自在」。可这世间，自在最贵。" },
    WeaponDef { id: "wp_xuantie_jian", name: "玄铁重剑", tier: 2, dmg: (40, 60), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(7)], base_price: 12000, need_grade: Some('A'), desc: "重剑无锋，大巧不工。它不要你花哨，只要你有扛起它的力气，和放得下的心。" },
    WeaponDef { id: "wp_lixiao_feidao", name: "小李飞刀·例无虚发", tier: 2, dmg: (28, 42), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Pierce(8), WeaponSpecial::Stun(0.2)], base_price: 8200, need_grade: Some('B'), desc: "例无虚发，例不轻出。那把刀不在袖中，在你看不见的那段因果里，早已替你把命算好。" },
    WeaponDef { id: "wp_liumai_jian", name: "六脉神剑·少商剑", tier: 2, dmg: (34, 50), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((3, 3)), WeaponSpecial::Stun(0.1)], base_price: 8900, need_grade: Some('B'), desc: "以气为剑，指走六脉。少商一出，剑气自指间破空，不留刃伤，只留一段清到骨髓的凉意。" },
    WeaponDef { id: "wp_beiming_jian", name: "北冥神功·吸星剑", tier: 2, dmg: (30, 48), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Leech(6), WeaponSpecial::Stun(0.15)], base_price: 9800, need_grade: Some('A'), desc: "北冥吞海，吸星纳力。它把敌人的内力与生气一并吸入剑身，只问你——吃进去的，能吐得出来吗？" },
    WeaponDef { id: "wp_dugu_jiujian", name: "独孤九剑·破剑式", tier: 3, dmg: (40, 60), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Pierce(6), WeaponSpecial::Stun(0.2)], base_price: 20000, need_grade: Some('A'), desc: "专破天下剑法，剑到之处，招招都是破绽。独孤求败之后，再无人配他这一剑。" },
    WeaponDef { id: "wp_miwu_shenzhao", name: "移花接玉掌刃", tier: 1, dmg: (22, 34), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Leech(4)], base_price: 3600, need_grade: Some('C'), desc: "掌若移花，刃如接玉。它把别人的力借来还回去，还回去的那一下，往往比来势更狠。" },
    WeaponDef { id: "wp_jinhe_zhang", name: "降龙十八掌·亢龙有悔", tier: 2, dmg: (36, 54), ammo: None, dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Stun(0.25)], base_price: 9400, need_grade: Some('B'), desc: "亢龙有悔，盈不可久。一掌拍出，龙吟震荡，可最要命的，永远是收掌时那一瞬的「悔」。" },
    WeaponDef { id: "wp_tianmen_yuanshang", name: "天外飞仙·剑遁", tier: 3, dmg: (44, 64), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Pierce(6), WeaponSpecial::Stun(0.2)], base_price: 22000, need_grade: Some('A'), desc: "一瞬千年，剑自天外而来，人已远遁千里。你只看见剑光，看不见那个转身不再回头的人。" },
    WeaponDef { id: "wp_diyang_zhandou", name: "迪迦光之刃", tier: 2, dmg: (36, 52), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((5, 3)), WeaponSpecial::Stun(0.1)], base_price: 9800, need_grade: Some('B'), desc: "光凝聚成一柄利刃，划破黑暗的那一瞬，像把希望亲手递到了人间。可光散之后，你仍要独自走完剩下的路。" },
    WeaponDef { id: "wp_shoujia_qiluo", name: "奇犽·电光疾影", tier: 1, dmg: (28, 40), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Stun(0.2)], base_price: 4600, need_grade: Some('C'), desc: "雷霆缠身，身如疾影。你跑得比闪电还快，却始终甩不掉那个还在追你的过去。" },
    WeaponDef { id: "wp_jinghuo_zhang", name: "降妖真火扇", tier: 2, dmg: (34, 50), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((6, 3))], base_price: 8600, need_grade: Some('B'), desc: "一扇生风，二扇生火，三扇焚尽妖邪。扇面上那簇真火，专烧一切不该留在人间的东西。" },
    WeaponDef { id: "wp_jinlong_dao", name: "金蛇郎君·缠丝软剑", tier: 1, dmg: (26, 38), ammo: None, dmg_type: DamageType::Silver, special: &[WeaponSpecial::Leech(4), WeaponSpecial::Stun(0.1)], base_price: 4000, need_grade: Some('C'), desc: "软剑如丝，可缠可刺，藏着金蛇郎君那一门从不外传的狠。它最懂，柔情也能杀人。" },
    WeaponDef { id: "wp_zhenwu_baojian", name: "真武七星剑", tier: 3, dmg: (42, 60), ammo: None, dmg_type: DamageType::Holy, special: &[WeaponSpecial::Pierce(6), WeaponSpecial::Burn((4, 3))], base_price: 21000, need_grade: Some('A'), desc: "剑分七星，应北斗之数。真武传人仗之除魔，剑起时，七星方位自有天罡之力相护。" },
    // ==================== 增量扩充（第 4 批 · 数据子代理追加 2 件） ====================
    WeaponDef { id: "wp_yinggong_lian", name: "幽影连弩", desc: "弩臂压满暗影的叹息，十支箭矢在弦上排队等着替你了账。它不挑猎物，只挑还没学会躲的人。", tier: 1, dmg: (18, 26), ammo: Some(10), dmg_type: DamageType::Kinetic, special: &[WeaponSpecial::Pierce(2)], base_price: 1800, need_grade: Some('C') },
    WeaponDef { id: "wp_yangyan_dao", name: "烈焰斩马刀", desc: "刀身缠着一圈不肯熄的火线，劈下去连空气都先替你让路。斩马斩的从来不是马，是那个还没肯认输的人。", tier: 2, dmg: (28, 42), ammo: None, dmg_type: DamageType::Energy, special: &[WeaponSpecial::Burn((4, 2))], base_price: 6800, need_grade: Some('B') },
];

/// 按武器 id 查表
pub fn weapon_def(id: &str) -> Option<&'static WeaponDef> {
    WEAPONS.iter().find(|w| w.id == id)
}
